from collections import Counter
def f(inp):
    H,W=len(inp),len(inp[0]); seen=[[False]*W for _ in range(H)]
    cnt=Counter(v for r in inp for v in r)
    bg=cnt.most_common(1)[0][0]
    res=[r[:] for r in inp]
    def nb(i,j):
        for da,db in ((1,0),(-1,0),(0,1),(0,-1)): yield i+da,j+db
    for i in range(H):
        for j in range(W):
            if not seen[i][j]:
                # BFS same-value
                st=[(i,j)]; comp=[]; seen[i][j]=True; v=inp[i][j]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for x,y in nb(a,b):
                        if 0<=x<H and 0<=y<W and not seen[x][y] and inp[x][y]==v:
                            seen[x][y]=True; st.append((x,y))
                rs=[a for a,b in comp]; cs=[b for a,b in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                frame=all(inp[a][b]==v for a in range(r0,r1+1) for b in range(c0,c1+1))
                if v==bg or not frame: continue
                for a,b in comp:
                    corner=(a in (r0,r1) and b in (c0,c1))
